using OcctSharp.StepCafWorkspaces;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class LocalStepAssemblyTests {
 [Fact]public void ActualExternalAssemblyRepeatedOccurrencePlacementAndCopiedLifetime()=>BatchBJLocalStepWorkflow.Run();
 [Fact]public void ExactSelectedRootImportsOnlyThatNativeProduct(){var manifest=LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,["roots.step"]);using var workspace=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"roots.step",manifest);Assert.Equal(2,workspace.Roots.Count);Assert.NotEqual(workspace.Roots[0].ModelNumber,workspace.Roots[1].ModelNumber);using var result=workspace.Transfer([workspace.Roots[0].Id]);Assert.True(result.Completed);Assert.Single(result.FreeRoots);Assert.Equal(workspace.Roots[0],result.Roots.Single().Source);using var shape=result.CopyFreeRoot(1);Assert.True(shape.IsValid);Assert.Equal(6,shape.FaceCount);Assert.Empty(result.Occurrences);}
 [Fact]public void RootDomainsDuplicateSelectionConsumptionAndReadOnlyDiagnosticsAreEnforced(){var manifest=LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,BatchBJLocalStepWorkflow.AssemblyFiles);using var first=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"assembly.step",manifest);using var second=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"assembly.step",manifest,StepCafReadModes.Names);Assert.Throws<ArgumentException>(()=>first.Transfer([second.Roots[0].Id]));Assert.Throws<ArgumentOutOfRangeException>(()=>first.Transfer([first.Roots[0].Id,first.Roots[0].Id]));Assert.Throws<NotSupportedException>(()=>((IList<LocalStepFile>)first.Files).Clear());using var result=first.Transfer([first.Roots[0].Id]);Assert.True(result.Completed);Assert.Throws<InvalidOperationException>(()=>first.Transfer([first.Roots[0].Id]));first.Dispose();Assert.Throws<ObjectDisposedException>(()=>first.Transfer([first.Roots[0].Id]));BatchBJLocalStepWorkflow.Verify(result);}
 static string PrivateCopy(){string root=Path.Combine(Path.GetTempPath(),"BJ-tests-"+Guid.NewGuid());Directory.CreateDirectory(root);foreach(string name in BatchBJLocalStepWorkflow.AssemblyFiles)File.Copy(Path.Combine(BatchBJLocalStepWorkflow.Fixture,name),Path.Combine(root,name));return root;}
 [Theory][InlineData("../piece_part.stp")][InlineData("assembly.step")][InlineData("PIECE_PART.STP")][InlineData("missing.stp")]
 public void PathBearingCycleCaseAliasAndMissingEdgesFailBeforeTransfer(string reference){string root=PrivateCopy();try{string path=Path.Combine(root,"assembly.step");File.WriteAllText(path,File.ReadAllText(path).Replace("piece_part.stp",reference,StringComparison.Ordinal));var manifest=LocalStepAssemblyWorkspace.CaptureManifest(root,BatchBJLocalStepWorkflow.AssemblyFiles);Assert.ThrowsAny<Exception>(()=>LocalStepAssemblyWorkspace.Open(root,"assembly.step",manifest));}finally{Directory.Delete(root,true);}}
 [Fact]public void UnsupportedExternalFormatFailsBeforeNativeRecursiveRead(){string root=PrivateCopy();try{string path=Path.Combine(root,"assembly.step");File.WriteAllText(path,File.ReadAllText(path).Replace("STEP AP214","UNKNOWN",StringComparison.Ordinal));var manifest=LocalStepAssemblyWorkspace.CaptureManifest(root,BatchBJLocalStepWorkflow.AssemblyFiles);Assert.Throws<ArgumentException>(()=>LocalStepAssemblyWorkspace.Open(root,"assembly.step",manifest));}finally{Directory.Delete(root,true);}}
 [Fact]public void SourceRewriteFailsManifestButAlreadyStagedWorkspaceIsIndependent(){string root=PrivateCopy();try{var manifest=LocalStepAssemblyWorkspace.CaptureManifest(root,BatchBJLocalStepWorkflow.AssemblyFiles);using var workspace=LocalStepAssemblyWorkspace.Open(root,"assembly.step",manifest);File.AppendAllText(Path.Combine(root,"piece_part.stp"),"\n/* rewritten */\n");Assert.Throws<IOException>(()=>LocalStepAssemblyWorkspace.Open(root,"assembly.step",manifest));using var result=workspace.Transfer([workspace.Roots[0].Id]);BatchBJLocalStepWorkflow.Verify(result);}finally{Directory.Delete(root,true);}}
 [Theory][InlineData("CON.step")][InlineData("NUL")][InlineData("file?.step")][InlineData("../assembly.step")]
 public void WindowsReservedAndNonBasenameManifestNamesAreRejected(string name)=>Assert.Throws<ArgumentException>(()=>LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,[name]));
 [Fact]public void LazyManifestAndSelectionStopAtBudgetPlusOne(){int files=0;IEnumerable<string> FileNames(){while(true){++files;yield return "assembly.step";}}Assert.Throws<ArgumentException>(()=>LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,FileNames()));Assert.Equal(129,files);var manifest=LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,BatchBJLocalStepWorkflow.AssemblyFiles);using var workspace=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"assembly.step",manifest);int roots=0;IEnumerable<LocalStepRootId> Roots(){while(true){++roots;yield return workspace.Roots[0].Id;}}Assert.Throws<ArgumentOutOfRangeException>(()=>workspace.Transfer(Roots()));Assert.Equal(4097,roots);using var result=workspace.Transfer([workspace.Roots[0].Id]);Assert.True(result.Completed);}
 [Fact]public void PrivateModesStayIndependentAcrossWorkspaceImports(){var manifest=LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,BatchBJLocalStepWorkflow.AssemblyFiles);using var names=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"assembly.step",manifest,StepCafReadModes.Names);using var all=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"assembly.step",manifest);using var a=names.Transfer([names.Roots[0].Id]);using var b=all.Transfer([all.Roots[0].Id]);Assert.True(a.Completed);Assert.True(b.Completed);Assert.Equal("repeat",a.FreeRoots[0].Name);Assert.Equal(a.Occurrences.Count,b.Occurrences.Count);}
}
